import {escapeHTML as e} from './state.js';
import {days,weeklyConnections} from './data/days.js';
import {lessons,weeks} from './data/curriculum.js';
import {dayStatus,codeAccepted} from './daily-state.js';
import {pythonNotes} from './python-notes.js';

const exerciseFor=(d,exercises)=>exercises.find(x=>x.id===d.exerciseId);
export function dailyWeekSchedule(week,state,exercises){
 return `<section class="panel weekly-plan"><h3>按天学习 · 第 ${week.id} 周</h3><p>每天在同一页完成讲解、互动题和代码。时间包含调试与复盘，可拆成多次 30 分钟，不以停留时长判断完成。</p>${days.filter(d=>d.week===week.id).map(d=>{const s=dayStatus(d,state,exerciseFor(d,exercises));return `<details class="day-plan" ${d.day===1?'open':''}><summary><span>DAY ${d.day}</span><strong>${e(d.title)}</strong><small>${s.completed?'已完成':`${d.minutes} 分钟预算`}</small></summary><p>${e(d.goals[0])}</p><p class="small">${d.isLesson?'案例讲解 + 互动判断 + 代码观察':d.isReview?'周总结 + 综合测验 + 编程项目':'函数契约 + 编程实现 + 自动检查'} · 互动 ${s.correct}/${d.checks.length} · ${s.code?'代码已验证':'代码待验证'}</p><a class="btn btn-primary" href="#/day/${d.id}">${s.completed?'复习这一天':'进入当天学习'} →</a></details>`;}).join('')}</section>`;
}

export function dailyDashboard(state,exercises,legacyQuestions){
 const statuses=days.map(d=>dayStatus(d,state,exerciseFor(d,exercises)));
 const completed=statuses.filter(s=>s.completed).length;
 const next=days[statuses.findIndex(s=>!s.completed)]||days.at(-1);
 const correct=statuses.reduce((n,s)=>n+s.correct,0);
 const graded=exercises.filter(ex=>ex.tests.length>0),passed=graded.filter(ex=>codeAccepted(ex,state)||(!ex.id.startsWith('daily-')&&!state.codeResults[ex.id]?.codeHash&&state.codeResults[ex.id]?.passed===ex.tests.length)).length;
 return `<div class="page-heading"><div><h1>今天，把一个概念变成能运行的代码。</h1><p>按掌握情况推进 · 84 个每日单元 · 48 道编程任务（含 12 个周综合项目）</p></div></div><section class="panel daily-resume"><div><span class="eyebrow">WEEK ${next.week} · DAY ${next.day}</span><h2>${e(next.title)}</h2><p>${e(next.goals[0])}</p><a class="btn btn-primary" href="#/day/${next.id}">继续当天学习 →</a></div><div class="daily-resume-note"><b>今天的四件事</b><p>读懂案例 → 作答并修正 → 运行与提交代码 → 留下一条观察</p><small>旧版课文和笔记保留。新版按天进度单独记录，不由“已读”自动换算。</small></div></section><div class="stats-row"><div class="panel stat"><div><div class="stat-label">每日单元完成</div><div class="stat-value">${completed}<small>/ 84 天</small></div></div></div><div class="panel stat"><div><div class="stat-label">日内互动最近答对</div><div class="stat-value">${correct}<small>/ ${days.reduce((n,d)=>n+d.checks.length,0)} 题</small></div></div></div><div class="panel stat"><div><div class="stat-label">编程检查通过</div><div class="stat-value">${passed}<small>/ ${graded.length} 个挑战</small></div></div></div></div><div class="daily-weeks">${weeks.map(w=>`<section class="panel panel-pad"><span class="eyebrow">WEEK ${w.id}</span><h3>${e(w.title)}</h3><div class="daily-week-days">${days.filter(d=>d.week===w.id).map(d=>`<a href="#/day/${d.id}" class="${dayStatus(d,state,exerciseFor(d,exercises)).completed?'done':''}" aria-label="第 ${w.id} 周第 ${d.day} 天：${e(d.title)}">${d.day===7?'总结':d.day}</a>`).join('')}</div><a class="text-link" href="#/course/${w.id}">查看本周目标与安排 →</a></section>`).join('')}</div>`;
}

export function dayCompletion(day,state,exercise){
 const s=dayStatus(day,state,exercise);
 return `<div class="day-checklist"><span class="${s.read?'done':''}">${s.read?'✓':'○'} 讲解与推演已读</span><span class="${s.correct===day.checks.length?'done':''}">${s.correct===day.checks.length?'✓':'○'} 互动题 ${s.correct}/${day.checks.length}</span><span class="${s.code?'done':''}">${s.code?'✓':'○'} ${exercise.tests.length?'当前代码全部检查通过':'当前示例运行成功'}</span></div><button class="btn btn-primary" data-action="complete-day" data-id="${day.id}" ${!s.ready||s.completed?'disabled':''}>${s.completed?'当天学习已完成':'完成当天学习'}</button><p class="small muted" aria-live="polite">${s.completed?'完成记录已保存，可继续下一天。':s.ready?'已满足当天练习条件；可以记录完成。':'还需：'+s.missing.join('；')}。运行参考示例和查看解法不等同于独立实现能力。</p>`;
}

export function renderDay(day,state,exercise,editorHTML){
 const record=state.days[day.id]||{},lesson=lessons.find(l=>l.id===day.lessonId),position=days.indexOf(day),s=dayStatus(day,state,exercise);
 const reading=day.isLesson?`<div class="day-case"><h3>先从一个具体问题进入</h3><p>${e(day.guide.caseStudy)}</p></div><dl class="lesson-terms">${lesson.terms.map(t=>`<div><dt>${e(t.name)}</dt><dd>${e(t.meaning)}<p>例子：${e(t.example)}</p></dd></div>`).join('')}</dl>${lesson.sections.map(section=>`<section class="reading-section"><h3>${e(section.title)}</h3>${section.body.map(p=>`<p>${e(p)}</p>`).join('')}</section>`).join('')}<section class="reading-section"><h3>把机制拆得更细</h3><p>${e(day.guide.reasoning)}</p><h3>今天必须观察的改动</h3><p>${e(day.guide.experiment)}</p></section>`:`<div class="day-case"><h3>为什么要实现这个组件</h3><p>${e(exercise.context)}</p></div><section class="reading-section"><h3>先读接口，再写代码</h3><p>${e(exercise.contract)}</p><h3>实现路线</h3><ol>${exercise.steps.map(p=>`<li>${e(p)}</li>`).join('')}</ol><h3>一个容易写错的地方</h3><p>${e(exercise.mistake)}</p><h3>放回实际训练中看</h3><p>${e(exercise.transfer)}</p></section>`;
 const review=day.isReview?`<section class="panel daily-section" id="day-review"><span class="eyebrow">WEEKLY REVIEW</span><h2>把这一周连起来</h2><ol class="weekly-connections">${weeklyConnections[day.week].map(p=>`<li>${e(p)}</li>`).join('')}</ol><h3>六天学习回顾</h3><div class="week-evidence">${days.filter(d=>d.week===day.week&&d.day<7).map(d=>{const r=state.days[d.id]||{};return `<a href="#/day/${d.id}"><b>DAY ${d.day}</b><span>${e(d.title)}</span><small>${d.checks.filter(q=>r.answers?.[q.id]?.selected===q.answer).length}/${d.checks.length} 互动题已答对</small></a>`;}).join('')}</div><p>下面的综合测验与编程项目共同检查本周内容。错题可重做；项目需要通过整套代码检查，单纯运行样例不会算完成。</p></section>`:'';
 return `<a class="text-link" href="#/course/${day.week}">← 第 ${day.week} 周路线</a><div class="page-heading space-top"><div><span class="eyebrow">WEEK ${day.week} / DAY ${day.day} · ${day.isReview?'总结与综合验收':day.isLesson?'讲解与观察':'实现与调试'}</span><h1>${e(day.title)}</h1><p>${day.minutes} 分钟任务预算 · 自动保存代码、答题与复盘 · 随时分段继续</p></div></div><div class="day-layout"><div class="stack"><section class="panel daily-section"><h2>今天要达到什么效果</h2><ul>${day.goals.map(g=>`<li>${e(g)}</li>`).join('')}</ul><div class="day-blocks">${day.blocks.map(b=>`<div><b>${e(b.label)}</b><small>约 ${b.minutes} 分钟</small></div>`).join('')}</div><p class="small muted">这是包含思考、改错和复盘的预算，不是要求你把几段文字读满这些时间。只有 30 分钟时，先完成一块再继续。</p></section>${review}<section class="panel daily-section" id="day-learn" tabindex="-1"><span class="eyebrow">01 · UNDERSTAND</span><h2>讲解与案例</h2>${reading}<div class="day-trace"><h3>先预测，再逐步展开推演</h3><p class="small">在点下一步之前，试着预测会得到什么数值或关系。</p><ol id="trace-steps">${day.trace.map((t,i)=>`<li ${i?'hidden':''}>${e(t)}</li>`).join('')}</ol><button class="btn btn-small" data-action="trace-next">展开下一步</button><span class="small muted" id="trace-count">1 / ${day.trace.length}</span></div><button class="btn ${record.read?'':'btn-primary'}" data-action="day-read" data-id="${day.id}">${record.read?'已记录阅读 · 点击撤销':'我已读完并核对推演'}</button></section><section class="panel daily-section" id="day-questions" tabindex="-1"><span class="eyebrow">02 · CHECK</span><h2>${day.isReview?'本周综合理解检查':'现在做一道判断'}</h2><p>选择后提交才能得到反馈。答错可以修改；这里检查的是本日与此前已讲解的内容。</p>${day.checks.map((q,i)=>{const a=record.answers?.[q.id],correct=a?.selected===q.answer;return `<form class="daily-question" data-day="${day.id}" data-question="${q.id}"><fieldset><legend>${i+1}. ${e(q.question)}</legend>${q.options.map((option,j)=>`<label class="daily-option"><input type="radio" name="answer" value="${j}" ${a?.selected===j?'checked':''} required><span>${e(option)}</span></label>`).join('')}</fieldset><button class="btn btn-small" type="submit">${a?'重新检查':'检查答案'}</button>${a?`<div class="daily-feedback ${correct?'correct':'incorrect'}" role="status"><b>${correct?'判断正确':'还需要修正'}</b><p>${e(q.explanation)}</p>${!correct?'<button type="button" class="text-link section-button" data-action="lesson-section" data-id="day-learn">回到讲解再检查 ↑</button>':''}<small>已尝试 ${a.attempts} 次</small></div>`:''}</form>`;}).join('')}</section><section class="panel daily-section day-coding" id="day-code" tabindex="-1"><span class="eyebrow">03 · BUILD</span><h2>${day.isLesson?'运行、修改并对照输出':day.isReview?'本周综合编程项目':'今天的编程题'}</h2>${editorHTML}</section><section class="panel daily-section" id="day-reflect" tabindex="-1"><span class="eyebrow">04 · REFLECT</span><h2>${day.isReview?'保存本周总结':'保存今天的理解'}</h2><label for="day-reflection">${e(day.reflection)}</label><textarea class="field day-reflection" id="day-reflection" data-day="${day.id}" placeholder="例如：最初把分母写成总位置数，看到 PAD 用例失败后改成有效位置数。">${e(record.reflection||'')}</textarea><p class="small muted">复盘由你记录，不由 GPT 自动判分。导出进度时会一起保存。</p><div id="day-completion">${dayCompletion(day,state,exercise)}</div><div class="day-next">${position?`<a class="btn" href="#/day/${days[position-1].id}">← 前一天</a>`:''}${position<days.length-1?`<a class="btn" href="#/day/${days[position+1].id}">${s.completed?'继续下一天':'预览下一天'} →</a>`:'<a class="btn" href="#/dashboard">回到学习记录 →</a>'}</div></section></div><aside class="day-aside panel"><h3>当天学习导航</h3>${[['day-learn','1. 讲解与推演'],['day-questions','2. 互动检查'],['day-code','3. 编程与运行'],['day-reflect','4. 复盘与完成']].map(([id,title])=>`<button data-action="lesson-section" data-id="${id}">${title}</button>`).join('')}<div id="day-progress-mini">${s.correct}/${day.checks.length} 互动题 · ${s.code?'代码已验证':'代码待验证'}</div><p class="small muted">完成条件：标记讲解已读、修正互动题、成功运行当前示例或通过当前编程检查。代码修改后需重新验证。</p>${lesson?`<a class="text-link" href="#/lesson/${lesson.id}">原课文、笔记与资料 →</a>`:''}</aside></div>`;
}

export function challengeDescription(ex){
 return `<div class="challenge-contract"><p>${e(ex.summary)}</p><h3>${ex.tests.length?'函数契约':'今天怎样运行'}</h3><p>${e(ex.contract||ex.instructions.join(' '))}</p>${ex.examples?`<h3>输入输出样例</h3>${ex.examples.map((x,i)=>`<article class="io-example"><b>样例 ${i+1} · ${e(x.why)}</b><pre><code>${e(x.call)}</code></pre><span>预期返回</span><pre>${e(x.expected)}</pre></article>`).join('')}`:''}${ex.expectedOutput?`<details class="example-expected"><summary>查看原始示例预期输出</summary><pre>${e(ex.expectedOutput)}</pre></details>`:''}<details class="python-notes"><summary>Python 语法卡住时，看这些用法</summary>${pythonNotes(ex.solution).map(n=>`<h3>${e(n.title)}</h3><p>${e(n.body)}</p>`).join('')||'<p>本例按从上到下的顺序执行，先找到变量在哪里赋值，再追踪它们怎样参与输出。</p>'}</details>${ex.tests.length?`<details><summary>这道题会检查什么（${ex.tests.length} 项）</summary><ul>${ex.tests.map(t=>`<li>${e(t.name)}</li>`).join('')}</ul><p class="small muted">检查在本机 Python 运行时执行，用于学习反馈，不是防作弊考试。通过这些用例不表示覆盖所有可能输入。</p></details>`:''}</div>`;
}

export function practiceCatalog(state,exercises){
 const daily=exercises.filter(x=>x.day),legacy=exercises.filter(x=>x.tests.length&&!x.day);
 return `<div class="page-heading"><div><h1>编程题库：实现一个组件，验证一种能力。</h1><p>48 道每日与周综合任务 + 8 道专项练习 · 可运行样例、自定义调用和提交检查</p></div></div><div class="stack">${weeks.map(w=>`<section class="panel daily-section"><span class="eyebrow">WEEK ${w.id}</span><h2>${e(w.title)}</h2><div class="practice-grid">${daily.filter(ex=>ex.week===w.id).map(ex=>`<a href="#/day/w${ex.week}-d${ex.day}" class="practice-card"><span class="badge">${ex.day===7?'周综合项目':'第 '+ex.day+' 天'}</span><h3>${e(ex.title)}</h3><p>${e(ex.goal)}</p><small>${ex.tests.length} 项检查 · ${codeAccepted(ex,state)?'当前代码已通过':'等待实现'}</small></a>`).join('')}</div></section>`).join('')}<section class="panel daily-section"><h2>原有专项练习</h2><div class="practice-grid">${legacy.map(ex=>`<a class="practice-card" href="#/code/${ex.id}"><h3>${e(ex.title)}</h3><p>${e(ex.summary)}</p></a>`).join('')}</div></section></div>`;
}
